/**
 * Fluent builder for creating a Mesh. Use `pushStream()` to describe vertex
 * streams and `withIndexData()` to add optional indices.
 */
export class MeshBuilder {
    private _topology: MeshTopology = MeshTopology.TriangleList;
    private _frontFace: FrontFace = FrontFace.CounterClockwise;
    private _streams: VertexStream[] = [];
    private _ctx: WebGPUContext;
    private _indexBuffer?: IndexBuffer;

    constructor(ctx: WebGPUContext) {
        this._ctx = ctx;
    }

    /** Add a vertex stream using a builder callback. */
    pushStream(buildFunc: (builder: StreamBuilder) => void): this {
        const stream = new VertexStream();
        buildFunc(new StreamBuilder(stream, this._ctx));
        console.assert(stream.buffer !== undefined, "Vertex stream must have a buffer. Did you forget to call withData()?");
        this._streams.push(stream);
        return this;
    }

    withFrontFace(value: FrontFace): this {
        this._frontFace = value;
        return this;
    }

    withTopology(value: MeshTopology): this {
        this._topology = value;
        return this;
    }

    /**
     * Provide index data (Uint16Array or Uint32Array). If `keepOnCPU` is true the
     * original array buffer will be preserved on the resulting mesh's index buffer.
     */
    withIndexData(data: Uint16Array | Uint32Array, keepOnCPU: boolean = false): this {
        this._indexBuffer = mapUndefined(data, data => new IndexBuffer(data, this._ctx, keepOnCPU));
        return this;
    }

    build(): Mesh {
        console.assert(this._streams.length > 0, "Mesh must have at least one vertex stream.");
        return new Mesh(
            this._topology,
            this._frontFace,
            this._streams,
            this._indexBuffer,
        );
    }
}

/**
 * Lightweight Mesh representation containing vertex streams and an optional index buffer.
 * Use `MeshBuilder` to construct instances.
 */
export class Mesh {
    private _topology: MeshTopology;
    private _frontFace: FrontFace;
    private _streams: VertexStream[] = [];
    private _indexBuffer?: IndexBuffer;
    private _numVertices: number;

    /**
     * @internal
     */
    constructor(topology: MeshTopology, frontFace: FrontFace, streams: VertexStream[], indexBuffer?: IndexBuffer) {
        this._topology = topology;
        this._frontFace = frontFace;
        this._streams = streams;
        this._indexBuffer = indexBuffer;
        this._numVertices = this._streams[0].numVertices;

        this._streams.forEach(
            stream => console.assert(stream.numVertices === this._numVertices,
                "All vertex streams must have the same number of vertices."
            ));
    }

    /** The primitive topology for this mesh. */
    get topology(): MeshTopology {
        return this._topology;
    }

    /** The winding used to determine front-facing triangles. */
    get frontFace(): FrontFace {
        return this._frontFace;
    }

    get numStreams() {
        return this._streams.length;
    }

    get numVertices() {
        return this._numVertices;
    }

    /** Get the GPU-backed vertex buffer for a given stream index. */
    getVertexBuffer(streamIndex: number): Buffer {
        return this._streams[streamIndex].buffer!;
    }

    /** Get the stride (byte size) of a vertex in the requested stream. */
    getStreamStride(streamIndex: number): number {
        return this._streams[streamIndex].stride;
    }

    /** Get the declared attributes for a vertex stream. */
    getStreamAttributes(streamIndex: number): VertexAttribute[] {
        return this._streams[streamIndex].attributes;
    }

    /** Get the optional index buffer backing this mesh. */
    get indexBuffer(): Buffer | undefined {
        return this._indexBuffer?.buffer;
    }

    get indexFormat(): IndexFormat {
        return this._indexBuffer?.format ?? IndexFormat.Uint16;
    }

    get numIndices(): number {
        return this._indexBuffer?.count ?? 0;
    }
}

import {Shader} from "./Shader";
import {mapUndefined} from "./utils/mapUndefined";
import {WebGPUContext} from "./WebGPUContext";
import {Mesh} from "./Mesh";

export enum CullMode {
    None = 'none',
    Front = 'front',
    Back = 'back'
}

/**
 * Fluent builder for creating a GPURenderPipeline. Attach a `Shader` and
 * optionally a `Mesh` (to derive vertex buffer layouts) before calling `build()`.
 */
export class RenderPipelineBuilder {
    private _shader?: Shader;
    private _colorTargets: GPUColorTargetState[] = [];
    private _defaultColorState: GPUColorTargetState;
    private _ctx: WebGPUContext;
    private _vertexEntry: string | undefined = undefined;
    private _fragmentEntry: string | undefined = undefined;
    private _label: string | undefined = undefined;
    private _overrideConstants: Record<string, number> = {};
    private _cullMode: CullMode = CullMode.Back;
    private _mesh: Mesh | undefined = undefined;

    constructor(ctx: WebGPUContext) {
        this._ctx = ctx;
        this._defaultColorState = {
            format: ctx.format,
            blend: undefined,
            writeMask: GPUColorWrite.ALL
        }
    }

    /** Assign a human-readable label for the pipeline (useful in graphics debuggers). */
    withLabel(label: string): this {
        this._label = label;
        return this;
    }

    /** Set face-culling mode. Default is `Back`. */
    withCullMode(value: CullMode): this {
        this._cullMode = value;
        return this;
    }

    /** Provide a Mesh to automatically derive vertex buffer layouts. */
    withMesh(mesh: Mesh): this {
        this._mesh = mesh;
        return this;
    }

    /** Attach a compiled Shader to the pipeline. */
    withShader(shader: Shader): this {
        this._shader = shader;
        return this;
    }

    /** Select the shader entry point for the vertex stage. */
    withVertexShader(entry: string): this {
        this._vertexEntry = entry;
        return this;
    }

    /** Select the shader entry point for the fragment stage. */
    withFragmentShader(entry: string): this {
        this._fragmentEntry = entry;
        return this;
    }

    /** Add a color target with the given texture format. */
    withColorTarget(format: GPUTextureFormat): this {
        this._colorTargets.push({
            format,
            blend: undefined,
            writeMask: GPUColorWrite.ALL
        });
        return this;
    }

    /** Override a shader constant for specialization. */
    withOverrideConstant(id: string, value: number): this {
        this._overrideConstants[id] = value;
        return this;
    }

    withBlendMode(): this {
        this.lastColorTarget.blend = undefined;
        return this;
    }

    /**
     * Build and create the `RenderPipeline`. Throws if required pieces (shader/vertices)
     * are missing.
     */
    build(): RenderPipeline {
        if (!this._shader) {
            throw new Error("Shader not specified. Use withShader() to set the shader to use.");
        }

        const shader = this._shader!;

        if (this._vertexEntry === undefined) {
            throw new Error("Shader does not contain a vertex entry point. Use ShaderBuilder.withVertexShader() to set one.");
        }

        const colorTargets = this._colorTargets.length ? this._colorTargets : [this._defaultColorState];
        const primitive: GPUPrimitiveState | undefined = mapUndefined(this._mesh, mesh => ({
            topology: mesh.topology,
            frontFace: mesh.frontFace,
            cullMode: this._cullMode,
        }));

        const buffers = mapUndefined(this._mesh, mesh => {
            const buffers: GPUVertexBufferLayout[] = [];
            for (let i = 0; i < mesh.numStreams; ++i) {
               const attributes = mesh.getStreamAttributes(i)
                    .filter(attr => shader.hasVertexAttribute(attr.name))
                    .map(attr => ({
                        shaderLocation: shader.getVertexAttributeLocation(attr.name)!,
                        offset: attr.offset,
                        format: attr.format,
                    }));

                buffers.push({
                    arrayStride: mesh.getStreamStride(i),
                    stepMode: 'vertex',
                    attributes
                });
            }
            return buffers;
        });

        console.log(buffers);

        const desc: GPURenderPipelineDescriptor = {
            label: this._label,
            layout: shader.layout ?? "auto",
            primitive,
            vertex: {
                buffers,
                module: shader.inner,
                entryPoint: this._vertexEntry!,
                constants: this._overrideConstants
            },
            fragment: mapUndefined(this._fragmentEntry, entry => ({
                module: shader.inner,
                entryPoint: entry,
                targets: colorTargets,
                constants: this._overrideConstants
            }))
        }

        const inner = this._ctx.device.createRenderPipeline(desc);

        return new RenderPipeline(inner, shader);
    }

    private get lastColorTarget(): GPUColorTargetState {
        return this._colorTargets.length ? this._colorTargets[this._colorTargets.length - 1] : this._defaultColorState;
    }
}

/**
 * Thin wrapper around GPURenderPipeline exposing a small helper for attribute
 * location lookup. The underlying pipeline and shader are available for advanced use.
 */
export class RenderPipeline {
    private _inner: GPURenderPipeline;
    private _shader: Shader;

    constructor(inner: GPURenderPipeline, shader: Shader) {
        this._inner = inner;
        this._shader = shader;
    }

    /**
     * Internal accessor for the underlying GPURenderPipeline. Not intended for public use.
     * @internal
     */
    get inner(): GPURenderPipeline {
        return this._inner;
    }

    /**
     * Helper to get the shader-declared attribute location for a named attribute.
     */
    public getVertexAttributeLocation(name: string): number | undefined {
        return this._shader.getVertexAttributeLocation(name);
    }
}

